import {buildProductSelection} from '../../../lib/credit-engine/product-selection/engine.ts';
import {id,stable,same,rank} from '../../../lib/credit-engine/product-selection/common.ts';
export const fingerprint=e=>id('product-golden',e);
export const mechanical=r=>r.candidates.map(c=>[c.productFamily,c.fitLevel,c.rank,c.primaryCandidate]);
export const forbiddenKeys=['productScore','approvalProbability','approvalLikelihood','PD','expectedDecision','recommendedBank','approvedLimit','recommendedLoanAmount','overdraftLimit','creditLineLimit','revolverLimit','factoringLimit','guaranteeLimit','leaseAmount','productRate','recommendations','actionPlan'];
export function invariantFailures(input,r){const out=[];const check=(v,c)=>{if(!v)out.push(c);};
 const walk=v=>{if(v&&typeof v==='object')for(const[k,n]of Object.entries(v)){check(!forbiddenKeys.includes(k),'FORBIDDEN_FIELD:'+k);walk(n);}};walk(r);
 check(r.candidates.length===7&&new Set(r.candidates.map(c=>c.productFamily)).size===7,'REGISTRY_COMPLETENESS');check(r.primaryCandidateProducts.length<=3,'PRIMARY_LIMIT');check(rank(r.confidence)<=rank(input.creditAssessment.confidence),'CONFIDENCE_PROMOTION');check(!r.comparable||r.status==='ASSESSED'&&input.creditAssessment.comparable&&input.debtCapacity.comparable,'COMPARABILITY');
 for(const c of r.candidates){check(!c.primaryCandidate||['STRONG_MATCH','MODERATE_MATCH','CONDITIONAL_MATCH'].includes(c.fitLevel),'PRIMARY_FIT');check(rank(c.confidence)<=rank(input.creditAssessment.confidence),'CANDIDATE_CONFIDENCE');check(c.productFamily==='TERM_LOAN'||!c.principalReferences.length,'ANNUITY_REFERENCE_LEAK');check(c.productFamily!=='FACTORING'||c.fitLevel!=='STRONG_MATCH','FACTORING_NO_INVOICE');check(c.portfolioObligationIds.every(id=>input.creditPortfolio?.obligations.some(o=>o.obligationId===id)),'DANGLING_PORTFOLIO');check(c.contextFactIds.every(id=>input.contextAssessment.facts.some(f=>f.factId===id)),'DANGLING_CONTEXT');}
 check(same(r.indexReference,input.creditAssessment.indexReference),'INDEX_IMMUTABLE_REFERENCE');check(same(r.readinessReference,input.creditAssessment.readinessReference),'READINESS_IMMUTABLE_REFERENCE');
 if(['INSUFFICIENT_DATA','NOT_RATABLE_GLOBAL_STOP'].includes(r.status))check(r.primaryCandidateProducts.length===0&&r.candidates.every(c=>c.rank===null),'BLOCKED_RANKING');return out;
}
export function expectations(e,r,error=null){const mismatches=[],ex=e.expected;const check=(ok,code,expected,actual,level='HARD')=>{if(!ok)mismatches.push({code,expected,actual,level});};
 if(ex.invalid){check(!!error?.includes(ex.invalid),'EXPECTED_REJECTION',ex.invalid,error);return mismatches;}
 check(!!r&&!error,'EXECUTION',true,error);if(!r)return mismatches;
 for(const key of ['status','confidence','comparable','primaryCandidateProducts'])if(Object.hasOwn(ex,key))check(stable(r[key])===stable(ex[key]),key,ex[key],r[key]);
 for(const s of ex.candidates??[]){const c=r.candidates.find(c=>c.productFamily===s.productFamily);check(!!c,'REQUIRED_CANDIDATE',s.productFamily,null);if(!c)continue;for(const[k,v]of Object.entries(s)){if(k==='productFamily')continue;if(k==='requiredReason')check([...c.supportReasonCodes,...c.constraintReasonCodes].includes(v),'REASON',v,c.supportReasonCodes);else if(k==='dataRequirement')check(c.dataRequirements.some(q=>q.code===v.code&&q.status===v.status),'DATA_REQUIREMENT',v,c.dataRequirements);else if(k==='scenarioCount')check(c.principalReferences.length===v,'SCENARIO_COUNT',v,c.principalReferences.length);else check(stable(c[k])===stable(v),k,v,c[k]);}}
 for(const p of ex.forbiddenCandidates??[])check(!r.candidates.some(c=>c.productFamily===p),'FORBIDDEN_CANDIDATE',p,r.candidates.map(c=>c.productFamily));
 for(const[k,v]of Object.entries(ex.summary??{}))check(stable(r.summary[k])===stable(v),'SUMMARY_'+k,v,r.summary[k]);
 for(const[k,v]of Object.entries(ex.requested??{}))check(stable(r.requestedProductComparison[k])===stable(v),'REQUESTED_'+k,v,r.requestedProductComparison[k]);
 for(const code of invariantFailures(e.input,r))check(false,code,true,false);
 if(ex.upstreamReadiness)check(e.input.financingReadiness.level===ex.upstreamReadiness,'READINESS_PREMISE',ex.upstreamReadiness,e.input.financingReadiness.level);
 if(ex.defect){const fs=e.input.riskAssessment.findings,d=fs.find(f=>f.code==='RISK-BKI-CURRENT-OVERDUE');check(d?.severity==='MEDIUM'&&d.reasonCodes.includes('CURRENT_OVERDUE')&&!fs.some(f=>f.code==='RISK-BKI-HISTORICAL-DELINQUENCY'||f.reasonCodes.some(c=>/^DELINQUENCY_/.test(c))),'PERMANENT_DEFECT_CHAIN',true,fs.map(f=>f.reasonCodes));}
 return mismatches;
}
export function compareProducts(a,b,kind='MECHANICS'){return stable(kind==='ORDER'?a.candidates.map(c=>c.productFamily):kind==='HEADROOM'?a.debtCapacityReference:mechanical(a))===stable(kind==='ORDER'?b.candidates.map(c=>c.productFamily):kind==='HEADROOM'?b.debtCapacityReference:mechanical(b));}
export function runProductPack(pack){for(const e of pack.entries)if(pack.fingerprints[e.caseId]!==fingerprint(e))throw Error('PRODUCT_GOLDEN_FINGERPRINT_MISMATCH');const rs=pack.entries.map(e=>{const before=stable(e.input);let actual=null,error=null;try{actual=buildProductSelection(e.input);}catch(ex){error=ex.message;}const mismatches=expectations(e,actual,error);if(before!==stable(e.input))mismatches.push({code:'UPSTREAM_MUTATED',level:'HARD'});return {caseId:e.caseId,actual,error,mismatches};});for(const e of pack.entries){const r=rs.find(v=>v.caseId===e.caseId);for(const other of e.expected.sameMechanicsAs??[]){const b=rs.find(v=>v.caseId===other);if(!r.actual||!b?.actual||!compareProducts(r.actual,b.actual))r.mismatches.push({code:'PAIRWISE_MISMATCH',level:'HARD',other});}}return rs.map(r=>({...r,result:r.mismatches.some(m=>m.level==='HARD')?'FAIL':r.mismatches.length?'REVIEW':'PASS'}));}
